package com.bplus.share;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Build;import android.provider.*;import org.json.*;import java.util.*;import java.io.*;
/** Exact-URI local deletion, verified after the operation. No filename search or broad storage grant. */
public final class FileDelete{
 public static final int REQUEST=819,PICK=820;private final Activity a;private final ArrayList<JSONObject> files;private final Runnable done;private final String thread;private final Set<String> removed=new HashSet<>(),seen=new HashSet<>();private final ArrayList<String> failures=new ArrayList<>();private final StringBuilder diagnostic=new StringBuilder();private int index,deleted,already;private JSONObject current;private Uri original,waiting;private boolean systemDeletes,picking;
 public FileDelete(Activity a,String thread,ArrayList<JSONObject> files,Runnable done){this.a=a;this.thread=thread;this.files=files;this.done=done;}
 public void start(){next();}
 private void log(String stage,Uri u,Exception e){diagnostic.append(stage).append(" | ").append(u==null?"no URI":u.toString()).append(" | API ").append(Build.VERSION.SDK_INT).append(" | ").append(e==null?"":e.getClass().getSimpleName()+": "+e.getMessage()).append("\n");Store.set("lastLocalDeleteDiagnostic",diagnostic.toString());}
 /** gone is conservative: permission/provider errors are not absence. */
 private boolean gone(Uri u){boolean noRow=false;try(Cursor c=a.getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){noRow=c!=null&&c.getCount()==0;}catch(SecurityException e){return false;}catch(Exception ignored){}try(android.content.res.AssetFileDescriptor f=a.getContentResolver().openAssetFileDescriptor(u,"r")){return false;}catch(FileNotFoundException e){return noRow;}catch(Exception e){return false;}}
 private boolean erase(Uri u)throws Exception{return DocumentsContract.isDocumentUri(a,u)?DocumentsContract.deleteDocument(a.getContentResolver(),u):a.getContentResolver().delete(u,null,null)>0;}
 private void next(){while(index<files.size()){current=files.get(index++);original=FileCards.uri(current);if(original==null){fail(R.string.delete_no_reference);continue;}if(!seen.add(original.toString()))continue;if(gone(original)){success(true);continue;}try{boolean result=erase(original);log("direct result="+result,original,null);if(gone(original)){success(false);continue;}}catch(SecurityException e){log("direct denied",original,e);if(Build.VERSION.SDK_INT>=29&&e instanceof RecoverableSecurityException&&consent(((RecoverableSecurityException)e).getUserAction().getActionIntent().getIntentSender(),original,false))return;}catch(Exception e){log("direct error",original,e);}if(mediaConsent(original))return;if(pickGrant())return;fail(R.string.delete_refused);}finish();}
 private boolean mediaConsent(Uri u){if(Build.VERSION.SDK_INT<30)return false;try{Uri media="media".equals(u.getAuthority())?u:MediaStore.getMediaUri(a,u);if(media==null||!"media".equals(media.getAuthority()))return false;return consent(MediaStore.createDeleteRequest(a.getContentResolver(),Collections.singletonList(media)).getIntentSender(),media,true);}catch(Exception e){log("media consent unavailable",u,e);return false;}}
 private boolean consent(IntentSender sender,Uri u,boolean deletes){try{waiting=u;systemDeletes=deletes;a.startIntentSenderForResult(sender,REQUEST,null,0,0,0);return true;}catch(Exception e){waiting=null;log("consent launch",u,e);return false;}}
 private boolean pickGrant(){try{picking=true;new AppDialog(a).setTitle(R.string.delete_grant_title).setMessage(a.getString(R.string.delete_grant_note,current.optString("name"))).setNegativeButton(R.string.cancel,(d,n)->{picking=false;fail(R.string.delete_cancelled);next();}).setOnCancelListener(d->{picking=false;fail(R.string.delete_cancelled);next();}).setPositiveButton(R.string.continue_label,(d,n)->{try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(Build.VERSION.SDK_INT>=26)i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,original);a.startActivityForResult(i,PICK);}catch(Exception e){picking=false;log("picker launch",original,e);fail(R.string.delete_refused);next();}}).show();return true;}catch(Exception e){picking=false;log("picker unavailable",original,e);return false;}}
 private Uri media(Uri u){try{return "media".equals(u.getAuthority())?u:MediaStore.getMediaUri(a,u);}catch(Exception e){return null;}}
 private boolean same(Uri selected){if(original.equals(selected))return true;try(android.os.ParcelFileDescriptor one=a.getContentResolver().openFileDescriptor(original,"r");android.os.ParcelFileDescriptor two=a.getContentResolver().openFileDescriptor(selected,"r")){if(one!=null&&two!=null){android.system.StructStat x=android.system.Os.fstat(one.getFileDescriptor()),y=android.system.Os.fstat(two.getFileDescriptor());if(x.st_ino>0&&x.st_ino==y.st_ino&&x.st_dev==y.st_dev)return true;}}catch(Exception ignored){}Uri one=media(original),two=media(selected);if(one!=null&&two!=null&&one.equals(two))return true;try{if(one!=null&&"com.android.providers.downloads.documents".equals(selected.getAuthority())){String id=DocumentsContract.getDocumentId(selected);String row=one.getLastPathSegment();return (one.getPath().contains("/downloads/")||one.getPath().contains("/file/"))&&one.getPathSegments().get(0).startsWith("external")&&id.equals("msf:"+row);}if(Build.VERSION.SDK_INT>=29&&one!=null){Uri doc=MediaStore.getDocumentUri(a,one);if(selected.equals(doc))return true;}}catch(Exception ignored){}return false;}
 public boolean result(int request,int result,Intent data){if(request==PICK&&picking){picking=false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){fail(R.string.delete_cancelled);next();return true;}Uri selected=data.getData();if(!same(selected)){log("picker identity mismatch",selected,null);fail(R.string.delete_wrong_file);next();return true;}try{a.getContentResolver().takePersistableUriPermission(selected,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}try{boolean resultDelete=erase(selected);log("SAF result="+resultDelete,selected,null);if(gone(original)&&gone(selected))success(false);else fail(R.string.delete_not_verified);}catch(Exception e){log("SAF delete error",selected,e);fail(R.string.delete_read_only);}next();return true;}if(request!=REQUEST||waiting==null)return false;Uri u=waiting;waiting=null;if(result!=Activity.RESULT_OK){fail(R.string.delete_cancelled);next();return true;}try{if(!systemDeletes)erase(u);if(gone(original)&&gone(u)){success(false);next();return true;}log("consent returned but file remains",u,null);}catch(Exception e){log("consent retry",u,e);}if(!pickGrant()){fail(R.string.delete_not_verified);next();}return true;}
 private void success(boolean wasGone){if(wasGone)already++;else deleted++;String uri=current.optString("uri");for(JSONObject m:files)if(uri.equals(m.optString("uri")))removed.add(ChatRules.key(m));Recall.retireUri(uri);try{JSONArray library=new JSONArray(Store.get("library","[]")),kept=new JSONArray();for(int i=0;i<library.length();i++){JSONObject item=library.optJSONObject(i);if(item!=null&&!uri.equals(item.optString("uri")))kept.put(item);}Store.set("library",kept.toString());}catch(Exception ignored){}log(wasGone?"already absent":"verified absent",original,null);}
 private void finish(){synchronized(Store.class){JSONArray t=Store.thread(thread),out=new JSONArray();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&removed.contains(ChatRules.key(m))){if(!thread.startsWith("live_"))continue;m.remove("uri");try{m.put("localFileDeleted",true);}catch(Exception ignored){}}out.put(m);}Store.saveThread(thread,out);}done.run();StringBuilder result=new StringBuilder(a.getString(R.string.delete_verified_summary,deleted,already,failures.size()));for(String f:failures)result.append("\n\n").append(f);result.append("\n\n").append(a.getString(R.string.delete_verified_cards));new AppDialog(a).setTitle(R.string.action_delete).setMessage(result.toString()).setNeutralButton(R.string.copy_details,(d,n)->PairUi.copy(a,diagnostic.toString())).setPositiveButton(android.R.string.ok,null).show();}
 private void fail(int reason){failures.add(current.optString("name")+"\n"+a.getString(reason));}
}
